  r.config();r.decoder.next=VideoDecoderContract.Outcome.INPUT_REJECTED;r.data(small,2);check(r.plane.rejected()==1&&r.plane.accepted()==0&&r.plane.takeAccountingAck().count==1,"rejected input accounting no display");log("rejected-input-ack",r,"REJECTED fake decoder input credited under explicit synthetic policy");
